command:
cd /app && python3 - <<'PY'
p='worktree_commit.go'
s=open(p).read()
# Change appendMergeParent to not remove
old='''func (w *Worktree) appendMergeParent(opts *CommitOptions) error {
\tmergeHead, err := w.readMergeHead()
\tif err != nil {
\t\tif os.IsNotExist(err) {
\t\t\treturn nil
\t\t}
\t\treturn err
\t}

\tfor _, parent := range opts.Parents {
\t\tif parent == mergeHead {
\t\t\treturn w.removeMergeHead()
\t\t}
\t}

\topts.Parents = append(opts.Parents, mergeHead)
\treturn w.removeMergeHead()
}'''
new='''func (w *Worktree) appendMergeParent(opts *CommitOptions) error {
\tmergeHead, err := w.readMergeHead()
\tif err != nil {
\t\tif os.IsNotExist(err) {
\t\t\treturn nil
\t\t}
\t\treturn err
\t}

\tfor _, parent := range opts.Parents {
\t\tif parent == mergeHead {
\t\t\treturn nil
\t\t}
\t}

\topts.Parents = append(opts.Parents, mergeHead)
\treturn nil
}'''
assert old in s
s=s.replace(old,new)
# Change final return to remove merge head after successful updateHEAD
old2='''\tcommit, err := w.buildCommitObject(msg, opts, treeHash)
\tif err != nil {
\t\treturn plumbing.ZeroHash, err
\t}

\treturn commit, w.updateHEAD(commit)
}'''
new2='''\tcommit, err := w.buildCommitObject(msg, opts, treeHash)
\tif err != nil {
\t\treturn plumbing.ZeroHash, err
\t}

\tif err := w.updateHEAD(commit); err != nil {
\t\treturn plumbing.ZeroHash, err
\t}

\tif err := w.removeMergeHead(); err != nil {
\t\treturn plumbing.ZeroHash, err
\t}

\treturn commit, nil
}'''
assert old2 in s
s=s.replace(old2,new2)
open(p,'w').write(s)
PY
gofmt -w worktree_commit.go && go build ./... && go test . -run 'TestMerge|TestCommit' -count=1 2>&1 | tail -20
